for aid,name,slug,remote,uploader,cat,mood,cue,start,end in SFX:
 a={'id':aid,'name':name,'kind':'sfx',**inspect(AUDIO/'sfx'/f'{aid}.mp3'),'sourceUrl':f'https://www.myinstants.com/en/instant/{slug}/','downloadUrl':f'https://www.myinstants.com/media/sounds/{remote}','creator':None,'uploader':uploader,'creatorVerified':False,'category':cat,'mood':mood,'cue':cue,'licenseStatus':'preview_only','previewOnly':True,'commercialReady':False,'licenseSummary':'Public soundboard download; original rights and commercial reuse permission are unverified. Local experiment only until separately cleared.','licenseEvidence':{'url':TERMS,'observedAt':OBSERVED,'summary':'The site grants limited personal noncommercial access. User uploads and a download button do not establish a downstream commercial synchronization license.'},'attribution':None,'trim':{'startSeconds':start,'endSeconds':round(end or max(.05,inspect(AUDIO/'sfx'/f'{aid}.mp3')['durationSeconds']-.025),3)},'suggestedGainDb':-6,'acquiredAt':OBSERVED,'audioVerification':'ffprobe decoded metadata and file signature; identity follows the named source page; no human listening audit in this step.'}
