b=copy.deepcopy(a)
b.update({'id':'badly','name':'Badly — Alex-Productions',**inspect(AUDIO/'music/badly-alex-productions.mp3'),'sourceUrl':'https://onsound.eu/track/badly-phonk/','downloadUrl':'https://media.onsound.eu/2024/07/02111858/Badly--1.mp3','category':'energetic_phonk','mood':['energetic','aggressive','punchy'],'cue':'A quick music entrance: source0–18.8s gives a short rising intro and a strong transient at about0.95s. Use a scratch or BRUH to end the phrase.','attribution':'Phonk Powerful | Badly by Alex-Productions\nhttps://youtu.be/ayDwvqgY-JQ\nMusic promoted by https://onsound.eu/','trim':{'startSeconds':0,'endSeconds':18.8},'alternateTrims':[],'dropSeconds':0.95,'dropOffsetInRecommendedTrimSeconds':0.95,'bpmEstimate':130,'bpmSource':'Creator player metadata and downloaded MP3 TBPM tag both specify130.','timingEvidence':'The first strong energy transient is measured at0.95s after a short rising intro. The file and creator-player metadata specify130BPM. This cue is not a human-auditioned downbeat.','audioVerification':'Decoded by FFmpeg; waveform inspected. Creator file metadata identifies FL Studio20 and release year2024. No claim this is the song in the supplied Instagram reel.'})
b['licenseEvidence']={'url':b['sourceUrl'],'observedAt':OBSERVED,'localEvidencePath':str(ROOT/'experiments/meme-audio/onsound-badly-license-evidence.txt'),'summary':'Read directly from the creator product page: social media and monetized videos with credit allowed; paid advertising and listed other contexts require a paid license. The downloaded file is the normal Badly version, not the slowed FMA variant.'}
