c={'schemaVersion':1,'createdAt':OBSERVED,'purpose':'Local experiments with actual downloaded meme sound effects and creator-supplied phonk, replacing procedural demo audio.','assets':assets,'policy':{'defaultUse':'local_experiment','publicRedistributionOfSourceFiles':False,'publishingRequires': 'Every asset must have rights for the intended placement; attribution alone does not clear preview_only assets. Use source links instead of redistributing the raw files.','syntheticAudio':False},'timingConvention':'All seconds are source-file time. trim.endSeconds is exclusive. The renderer should trim before timing/ducking the clip. Do not confuse source dropSeconds with output placement.'}
(ROOT/'experiments/meme-audio/catalog.json').write_text(json.dumps(c,indent=2)+'\n')
print(json.dumps([{'id':a['id'],'duration':a['durationSeconds'],'trim':a['trim'],'licenseStatus':a['licenseStatus']} for a in assets],indent=2))
